scripts.杨影枫对话.txt:
	If ($Event == 304) @Label1;
	If ($Event == 305) @Label2;
	If ($Event == 340) @Label3;
	Goto @end;

@Label1:
	If ($Talkyyf055a == 0) @Talk0;
	If ($Talkyyf055a == 1) @Talk1;
	If ($Talkyyf055a == 2) @Talk2;
	Goto @end;
@Talk0:
	If ($NaLanZhenSense >= 20) @AddSenseEnd;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd:
	Say("杨影枫：真儿，这里面黑漆漆的，不知藏有什么危险，我们要小心！", 2);
	Say("纳兰真：好的……影枫哥哥，你是不是觉得我太任性了？", 12);
	Say("杨影枫：……没有啊，你只是对什么都感到好奇，毕竟还是小孩子嘛！", 3);
	Say("纳兰真：谁说我是小孩子！", 11);
	Say("杨影枫：嘻嘻……", 3);
	Assign($Talkyyf055a, 1);
	Goto @end;
@Talk1:
	If ($NaLanZhenSense >= 20) @AddSenseEnd1;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd1:
	Say("杨影枫：真儿，生气啦？", 3);
	Say("纳兰真：才没有呢！只是……你以后不要再说我是小孩子了，好吗？", 12);
	Say("杨影枫：真儿……对不起！", 7);
	Say("纳兰真：没事，我才没有那么小气呢！", 9);
	Assign($Talkyyf055a, 2);
	Goto @end;
@Talk2:
	If ($NaLanZhenSense >= 20) @AddSenseEnd2;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd2:
	Say("纳兰真：影枫哥哥，从小到大一直都没有什么人陪我玩，这次你能陪我来这里，我真的很开心呀！", 9);
	Goto @end;

	
@Label2:
	If ($Talkyyf055b == 0) @Talk3;
	If ($Talkyyf055b == 1) @Talk4;
	Goto @end;
@Talk3:
	If ($NaLanZhenSense >= 20) @AddSenseEnd3;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd3:
	Say("纳兰真：这些吸血蝙蝠真可怕呀！", 9);
	Say("杨影枫：真儿，你的伤……", 5);
	Say("纳兰真：没事！我们再往里走走，看看还有什么好玩的东西。", 9);
	Say("杨影枫：真儿……", 2);
	Assign($Talkyyf055b, 1);
	Goto @end;
@Talk4:
	If ($NaLanZhenSense >= 20) @AddSenseEnd4;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd4:
	Say("纳兰真：影枫哥哥，我们再往里走走，看看还有什么好玩的东西。", 9);
	Goto @end;	

@Label3:
	If ($NaLanZhenSense >= 20) @AddSenseEnd5;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd5:
	Say("纳兰真：影枫哥哥，你新练的神功真厉害啊！", 9);
	Goto @end;
	
@end:
	Return;

scripts.吸血蝙蝠死亡.txt:
	Add($Deadbat, 1);
	If ($Deadbat <> 14) @end;
	If ($Event <> 304) @end;
	Sleep(500);
	SetPlayerState(0);
	Talk(5290, 5321);
	SetNpcKind("纳兰真", 1);
	SetNpcKind("杨影枫", 2);
	FullLife();
	SetNpcKind("杨影枫", 3);
	SetNpcKind("纳兰真", 2);
	FullLife();
	Assign($Event, 305);
	SetMapTrap(2, "Trap02.txt");
	Goto @end;
@end:
	Return;

traps.Trap01.txt:
	If ($Event == 308) @Label1;
	If ($Event == 304) @Label4;
	If ($Event == 305) @Label4;
	If ($Event == 309) @Label3;
	
	ClearBody();
	SaveObj();
	FadeOut();
	LoadMap("map_054_北山.map");
	LoadNpc("beishan-sharenfeng.npc");
    SaveNpc("temp.npc");
	LoadObj("map054_obj.obj");
	SetPlayerPos(9,105);
	SetPlayerDir(0);
	FadeIn();
	Return;

@Label1:
	If ($SelectVal == 1) @Label2;
	Return;

@Label2:
	Say("杨影枫：可是……", 7);
	Sleep(500);
	PlayerGotoDir(6, 1);
	Say("杨影枫：我此时回去，恐怕也难以对纳兰前辈交代，万一真儿有什么事……", 7);
	Sleep(500);
	PlayerGotoDir(2, 1);
	Sleep(500);
	PlayerGoto(2, 27);
	SetPlayerDir(7);
	Say("杨影枫：唉，我还是跟下去看看吧！", 7);
	Assign($Event, 309);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	AddToMemo(90531);
	Return;

@Label3:
	Say("杨影枫：唉，我还是跟下去看看吧！", 7);
	PlayerGotoDir(6, 1);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	Return;

@Label4:
	Talk(5271, 5271);
	Return;

@end:
	Return;

